arguments.command:
cat > src/CheckoutPricing.Application/CheckoutHandler.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Gold }

public sealed class CheckoutHandler
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
mkdir -p tests/CheckoutPricing.UnitTests/Acceptance
cat > tests/CheckoutPricing.UnitTests/Acceptance/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Acceptance;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var total = new CheckoutHandler().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | grep -v "^$" | head -20

